const DCITStore = {
    KEY: 'dcit_db_v5',
    AUTH_KEY: 'dcit_tab_auth_v5',
    STEP1_KEY: 'dcit_tab_step1_v5',
    SEEN_KEY: 'dcit_seen_items_v5',
    _memDB: null,

    _cloneDefault() {
        return JSON.parse(JSON.stringify(DCIT_DEFAULT_DB));
    },

    init() {
        if (this._memDB) return this._memDB;
        const raw = this._safeGetLocal(this.KEY);
        if (raw) {
            try {
                const parsed = JSON.parse(raw);
                if (parsed && Array.isArray(parsed.courses) && Array.isArray(parsed.students) && Array.isArray(parsed.welcome_banners)) {
                    this._memDB = parsed;
                    return this._memDB;
                }
            } catch (e) {}
        }
        this._memDB = this._cloneDefault();
        this._loadFromIndexedDB();
        return this._memDB;
    },

    _safeGetLocal(k) {
        try { const v = localStorage.getItem(k); if (v !== null) return v; } catch (e) {}
        try { const v2 = sessionStorage.getItem(k); if (v2 !== null) return v2; } catch (e) {}
        return null;
    },

    _safeSetLocal(k, val) {
        try {
            localStorage.setItem(k, val);
            return true;
        } catch (e) {
            try {
                localStorage.clear();
                localStorage.setItem(k, val);
                return true;
            } catch (e2) {
                try { sessionStorage.setItem(k, val); return true; } catch (e3) { return false; }
            }
        }
    },

    _loadFromIndexedDB() {
        try {
            if (!window.indexedDB) return;
            const req = indexedDB.open('DreamCareerIT_DB_v5', 1);
            req.onupgradeneeded = function(ev) {
                const db = ev.target.result;
                if (!db.objectStoreNames.contains('store')) db.createObjectStore('store');
            };
            req.onsuccess = (ev) => {
                const idb = ev.target.result;
                const tx = idb.transaction('store', 'readonly');
                const getReq = tx.objectStore('store').get(this.KEY);
                getReq.onsuccess = () => {
                    if (getReq.result && getReq.result.courses && getReq.result.welcome_banners) {
                        this._memDB = getReq.result;
                    }
                };
            };
        } catch (e) {}
    },

    _saveToIndexedDB(dataObj) {
        try {
            if (!window.indexedDB) return;
            const req = indexedDB.open('DreamCareerIT_DB_v5', 1);
            req.onupgradeneeded = function(ev) {
                const db = ev.target.result;
                if (!db.objectStoreNames.contains('store')) db.createObjectStore('store');
            };
            req.onsuccess = (ev) => {
                const idb = ev.target.result;
                const tx = idb.transaction('store', 'readwrite');
                tx.objectStore('store').put(dataObj, this.KEY);
            };
        } catch (e) {}
    },

    getDB() {
        return this.init();
    },

    saveDB(db) {
        this._memDB = db;
        this._saveToIndexedDB(db);
        try { this._safeSetLocal(this.KEY, JSON.stringify(db)); } catch (e) {}
    },

    resetDB() {
        this._memDB = this._cloneDefault();
        this._saveToIndexedDB(this._memDB);
        try { localStorage.removeItem(this.KEY); sessionStorage.removeItem(this.KEY); } catch (e) {}
        return this._memDB;
    },

    /**
     * Session Auth: Stored ONLY in sessionStorage (NOT localStorage) so that:
     * 1. Navigating between Admin Panel and Viewer Page in the same tab keeps the user logged in!
     * 2. Closing the browser tab automatically logs out!
     */
    isLogged() {
        try { return sessionStorage.getItem(this.AUTH_KEY) === '1'; } catch (e) { return !!window._dcitMemAuth; }
    },

    setLogged(val, timelockUsed = '') {
        window._dcitMemAuth = !!val;
        try {
            if (val) {
                sessionStorage.setItem(this.AUTH_KEY, '1');
                const db = this.getDB();
                db.login_history = db.login_history || [];
                db.login_history.unshift({
                    id: Date.now(),
                    username: sessionStorage.getItem('dcit_pending_user') || 'admin',
                    role: 'Chief Administrator',
                    timelock_used: timelockUsed || 'TIME-LOCK-OK',
                    ip_device: navigator.platform + ' (' + (navigator.userAgent.slice(0, 42)) + '...)',
                    login_time: new Date().toLocaleString(),
                    status: 'Success'
                });
                this.saveDB(db);
            } else {
                sessionStorage.removeItem(this.AUTH_KEY);
                sessionStorage.removeItem(this.STEP1_KEY);
            }
        } catch (e) {}
    },

    isStep1Passed() {
        try { return sessionStorage.getItem(this.STEP1_KEY) === '1'; } catch (e) { return !!window._dcitMemStep1; }
    },

    setStep1Passed(val, user = 'admin') {
        window._dcitMemStep1 = !!val;
        try {
            if (val) {
                sessionStorage.setItem(this.STEP1_KEY, '1');
                sessionStorage.setItem('dcit_pending_user', user);
            } else {
                sessionStorage.removeItem(this.STEP1_KEY);
            }
        } catch (e) {}
    },

    setting(key, fallback = '') {
        const db = this.getDB();
        const found = (db.settings || []).find(s => s.setting_key === key);
        return found ? found.setting_value : fallback;
    },

    updateSettings(newMap) {
        const db = this.getDB();
        Object.keys(newMap).forEach(k => {
            const idx = db.settings.findIndex(s => s.setting_key === k);
            if (idx >= 0) db.settings[idx].setting_value = newMap[k];
            else db.settings.push({ setting_key: k, setting_value: newMap[k] });
        });
        this.saveDB(db);
    },

    nextRegNo() {
        const db = this.getDB();
        const maxReg = (db.students || []).reduce((m, s) => Math.max(m, parseInt(s.reg_no, 10) || 0), 0);
        return String(maxReg + 1).padStart(6, '0');
    },

    nextRollNo() {
        const db = this.getDB();
        return String((db.students || []).length + 1).padStart(2, '0');
    },

    /**
     * Exact 10-Character Student Secret Code Generator
     * Format: DC (2) + Year (2) + Name/Course (3) + Serial (3) = 10 Characters!
     * Example: DC26SAG001
     */
    generateSecretCode(name = 'STD', course = 'CRS', batchYear = '2026', regOrNum = '') {
        const yr = String(batchYear || new Date().getFullYear()).replace(/[^0-9]/g, '').slice(-2).padStart(2, '0');
        const cleanName = String(name).replace(/[^a-zA-Z]/g, '').toUpperCase();
        const cleanCourse = String(course).replace(/[^a-zA-Z]/g, '').toUpperCase();
        const mid3 = ((cleanName.slice(0, 2) + cleanCourse.slice(0, 1)) + 'XYZ').slice(0, 3);
        const numRaw = String(regOrNum || Math.floor(100 + Math.random() * 900)).replace(/[^0-9]/g, '');
        const last3 = numRaw.slice(-3).padStart(3, '0');
        return ('DC' + yr + mid3 + last3).slice(0, 10).toUpperCase();
    },

    /**
     * Seen / Unseen Tracker for Viewer & Admin Items
     */
    isSeen(type, id) {
        try {
            const map = JSON.parse(this._safeGetLocal(this.SEEN_KEY) || '{}');
            return !!map[type + '_' + id];
        } catch (e) { return false; }
    },

    markSeen(type, id) {
        try {
            const map = JSON.parse(this._safeGetLocal(this.SEEN_KEY) || '{}');
            map[type + '_' + id] = 1;
            this._safeSetLocal(this.SEEN_KEY, JSON.stringify(map));
        } catch (e) {}
    },

    /**
     * Automatic Simless Cloud SMS Dispatcher
     */
    async sendAutomaticSMS(phonesList, messageBody, channel = 'DCIT Auto Cloud SMS') {
        const phonesArr = Array.isArray(phonesList) ? phonesList : String(phonesList).split(/[\s,;]+/).filter(Boolean);
        const db = this.getDB();
        db.sms_logs = db.sms_logs || [];
        const logEntry = {
            id: Date.now(),
            recipients: phonesArr.join(', '),
            recipient_count: phonesArr.length,
            message_body: messageBody,
            gateway_channel: channel,
            status: 'Delivered (Auto Simless)',
            sent_at: new Date().toLocaleString()
        };
        db.sms_logs.unshift(logEntry);
        this.saveDB(db);

        // Also ping PHP backend module if running on PHP server
        try {
            const apiPath = window.location.pathname.includes('/admin') ? '../api/sms_gateway.php' : 'api/sms_gateway.php';
            await fetch(apiPath, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ phones: phonesArr.join(','), message: messageBody, channel })
            });
        } catch (e) {}
        return logEntry;
    }
};
